3517	+  private TextChunk[] createTextChunks(FileHighlighter highlighter, int start, int end) {
3518	+    LOG.assertTrue(start <= end);
3519	+    List<TextChunk> result = new ArrayList<TextChunk>();
3520	+
3521	+    appendPrefix(result);
3522	+
3523	+    Lexer lexer = highlighter.getHighlightingLexer();
3524	+    CharSequence chars = myDocument.getCharsSequence();
3525	+    lexer.start(CharArrayUtil.fromSequence(chars));
3526	+
3527	+    for (int offset = start; offset < end; offset++) {
3528	+      if (chars.charAt(offset) == '\n') {
3529	+        end = offset;
3530	+        break;
3531	+      }
3532	+    }
3533	+
3534	+    boolean isBeginning = true;
3535	+
3536	+    while (lexer.getTokenType() != null) {
3537	+      try {
3538	+        int hiStart = lexer.getTokenStart();
3539	+        int hiEnd = lexer.getTokenEnd();
3540	+
3541	+        if (hiStart >= end) break;
3542	+
3543	+        hiStart = Math.max(hiStart, start);
3544	+        hiEnd = Math.min(hiEnd, end);
3545	+        if (hiStart >= hiEnd) { continue; }
3546	+
3547	+        String text = chars.subSequence(hiStart, hiEnd).toString();
3548	+        if (isBeginning && text.trim().length() == 0) continue;
3549	+        isBeginning = false;
3550	+        IElementType tokenType = lexer.getTokenType();
3551	+        TextAttributesKey[] tokenHighlights = highlighter.getTokenHighlights(tokenType);
3552	+
3553	+        RangeMarker intersectionMarker = getIntersectingMarker(hiStart, hiEnd);
3554	+        if (intersectionMarker != null) {
3555	+          processIntersectingRage(chars, hiStart, hiEnd, tokenHighlights, result, intersectionMarker);
3556	+        }
3557	+        else {
3558	+          result.add(new TextChunk(convertAttributes(tokenHighlights), text));
3559	+        }
3560	+      }
3561	+      finally {
3562	+        lexer.advance();
3563	+      }
3564	+    }
3565	+
3566	+    return result.toArray(new TextChunk[result.size()]);
3567	+  }
3568	+
3569	+  private RangeMarker getIntersectingMarker(int hiStart, int hiEnd) {
3570	+    for (int i = 0; i < myRangeMarkers.size(); i++) {
3571	+      RangeMarker marker = myRangeMarkers.get(i);
3572	+      if (marker.isValid() && rangeIntersect(hiStart, hiEnd, marker.getStartOffset(), marker.getEndOffset())) return marker;
3573	+    }
3574	+    return null;
3575	+  }
3576	+
3577	+  private void processIntersectingRage(CharSequence chars,
3578	+                                       int hiStart,
3579	+                                       int hiEnd,
3580	+                                       TextAttributesKey[] tokenHighlights,
3581	+                                       List<TextChunk> result,
3582	+                                       RangeMarker rangeMarker) {
3583	+    int usageStart = rangeMarker.getStartOffset();
3584	+    int usageEnd = rangeMarker.getEndOffset();
3585	+
3586	+    TextAttributes originalAttrs = convertAttributes(tokenHighlights);
3587	+    addChunk(chars, hiStart, Math.max(hiStart, usageStart), originalAttrs, false, result);
3588	+    addChunk(chars, Math.max(hiStart, usageStart), Math.min(hiEnd, usageEnd), originalAttrs, true, result);
3589	+    addChunk(chars, Math.min(hiEnd, usageEnd), hiEnd, originalAttrs, false, result);
3590	+  }
3591	+
3592	+  private void addChunk(CharSequence chars, int start, int end, TextAttributes originalAttrs, boolean bold, List<TextChunk> result) {
3593	+    if (start >= end) return;
3594	+    String rText = chars.subSequence(start, end).toString();
3595	+    TextAttributes attrs = bold
3596	+                           ? TextAttributes.merge(originalAttrs, new TextAttributes(null, null, null, null, Font.BOLD))
3597	+                           : originalAttrs;
3598	+    result.add(new TextChunk(attrs, rText));
3599	+  }
3600	+
3601	+  private static boolean rangeIntersect(int s1, int e1, int s2, int e2) {
3602	+    return s2 < s1 && s1 < e2 || s2 < e1 && e1 < e2
3603	+           || s1 < s2 && s2 < e1 || s1 < e2 && e2 < e1
3604	+           || s1 == s2 && e1 == e2;
3605	+  }
3606	+
3607	+  private TextAttributes convertAttributes(TextAttributesKey[] keys) {
3608	+    TextAttributes attrs = myColorsScheme.getAttributes(HighlighterColors.TEXT);
3609	+
3610	+    for (int i = 0; i < keys.length; i++) {
3611	+      TextAttributesKey key = keys[i];
3612	+      TextAttributes attrs2 = myColorsScheme.getAttributes(key);
3613	+      if (attrs2 != null) {
3614	+        attrs = TextAttributes.merge(attrs, attrs2);
3615	+      }
3616	+    }
3617	+
3618	+    attrs = attrs.clone();
3619	+    attrs.setFontType(Font.PLAIN);
3620	+    return attrs;
3621	+  }
3622	+
3623	+  private void appendPrefix(List<TextChunk> result) {
3624	+    StringBuffer buffer = new StringBuffer("(");
3625	+    buffer.append(myLineNumber + 1);
3626	+    buffer.append(", ");
3627	+    buffer.append(myColumnNumber + 1);
3628	+    buffer.append(") ");
3629	+    TextChunk prefixChunk = new TextChunk(myColorsScheme.getAttributes(UsageTreeColors.USAGE_LOCATION), buffer.toString());
3630	+    result.add(prefixChunk);
3631	+  }
